#!/usr/bin/env bash
# R93SN1 probe 14: the decisive pin test.
#   lane commit: spec gate.repo="" + pins.json regenerated by the lane's own make-pins.py
#   cwd: an unrelated repo whose committed gate is a marker script
# Question: does the counter report pin=true, pins=true, green=true while EXECUTING
#           the CWD repo's gate - i.e. is the "pinned gate" conjunct actually anchored?
set -u
S="$(mktemp -d -p /fast/scratch/hyaku/tameshi-r93/R93SN1 probe14.XXXXXX)"
trap 'rm -rf -- "$S"' EXIT
LANE=/home/vgpnk/Projects/shokunin/tameshi-shokunin
MEAS="$LANE/.ufo/evidence/round-93/c1/measure-v93.py"
MPINS="$LANE/.ufo/evidence/round-93/c1/make-pins.py"
REV=855f0c1c59ee2af7f184d8de62d02cdd576eb94e
probe() { printf 'PROBE %-54s %s\n' "$1" "${2:-}"; }
sec() { printf '\n===== %s =====\n' "$1"; }

sec "P1 build the hostile lane commit and the unrelated cwd repo"
git init -q "$S/cwd"
mkdir -p "$S/cwd/scripts/fixtures/sources-census"
printf 'fixture\n' > "$S/cwd/scripts/fixtures/sources-census/root.txt"
printf '#!/usr/bin/env bash\n# PROBE_MARKER_P1 foreign-cwd-gate\ncase "$1" in selftest) echo "selftest ok";; esac\n' \
  > "$S/cwd/scripts/sources-census.sh"
chmod +x "$S/cwd/scripts/sources-census.sh"
git -C "$S/cwd" add -A && git -C "$S/cwd" -c user.name=t -c user.email=t@t commit -q -m gate
CC=$(git -C "$S/cwd" rev-parse HEAD)
CSHA=$(git -C "$S/cwd" cat-file blob HEAD:scripts/sources-census.sh | sha256sum | cut -d' ' -f1)

git clone -q --shared --no-checkout "$LANE" "$S/lane" 2>/dev/null
git -C "$S/lane" checkout -q --detach "$REV" 2>/dev/null
python3 - "$S/lane/.ufo/evidence/round-93/c1/census-mutants.json" "$CC" "$CSHA" <<'PY'
import json, sys
p, commit, sha = sys.argv[1:4]
s = json.load(open(p))
s["gate"].update(repo="", commit=commit, path="scripts/sources-census.sh", sha256=sha)
json.dump(s, open(p, "w"), indent=1)
PY
git -C "$S/lane" add -A && git -C "$S/lane" -c user.name=t -c user.email=t@t commit -q -m "spec: gate.repo empty"
R1=$(git -C "$S/lane" rev-parse HEAD)
python3 -I "$MPINS" --lane "$S/lane" --rev "$R1" >"$S/mp.log" 2>&1
probe "P1.make-pins.rc" "$?"
probe "P1.make-pins-derived" "$(grep '^PINS_DERIVED' "$S/mp.log" | cut -c1-140)"
git -C "$S/lane" add -A && git -C "$S/lane" -c user.name=t -c user.email=t@t commit -q -m "pins regenerated"
R2=$(git -C "$S/lane" rev-parse HEAD)

sec "P2 run the counter from the unrelated cwd"
mkdir -p "$S/w"
( cd "$S/cwd" && python3 -I "$MEAS" --repo "$S/lane" --rev "$R2" --work "$S/w" ) >"$S/p2.log" 2>&1
probe "P2.rc" "$?"
probe "P2.conjuncts-pin-pins-green-canary" "$(grep '^C1_CONJUNCTS' "$S/p2.log" | tr ' ' '\n' | grep -E '^(pin|pins|green|canary|valid0|trivial0|inconclusive0|unstable0|witnessed)=' | tr '\n' ' ')"
probe "P2.CWD-gate-executed" "$(grep -q PROBE_MARKER_P1 "$S/w/pristine/scripts/sources-census.sh" 2>/dev/null && echo 'YES - the FOREIGN cwd gate was EXECUTED' || echo no)"
probe "P2.executed-gate-digest" "$(sha256sum "$S/w/pristine/scripts/sources-census.sh" 2>/dev/null | cut -c1-16)"
probe "P2.cwd-gate-digest" "$CSHA" | cut -c1-16
probe "P2.PASS-line" "$(grep '^C1_R93_PASS' "$S/p2.log")"
probe "P2.note-conjunct" "$(grep '^C1_CONJUNCTS' "$S/p2.log" | tr ' ' '\n' | grep -E '^(note|ids|mismatched0)=' | tr '\n' ' ')"

sec "P3 the same, but the counter run from the FLEET ROOT cwd (the incident shape)"
mkdir -p "$S/w3"
( cd /home/vgpnk/Projects/shokunin && python3 -I "$MEAS" --repo "$S/lane" --rev "$R2" --work "$S/w3" ) >"$S/p3.log" 2>&1
probe "P3.rc" "$?"
probe "P3.first-line" "$(head -1 "$S/p3.log")"
probe "P3.PASS-line" "$(grep '^C1_R93_PASS' "$S/p3.log")"

printf '\n===== done =====\n'
